-- Esquema MÍNIMO da Fase 4 (secretaria) para testes locais. Rodar após schema_comunidade.sql.
CREATE TABLE LISTA_ESTADO_CIVIL (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE CURSO_DEPENDENCIA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, CURSO_ID BIGINT NOT NULL, CURSO_REQUISITO_ID BIGINT NOT NULL);
CREATE TABLE INSCRICAO (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, USUARIO_ID BIGINT NULL,
  IGREJA_TELEFONE VARCHAR(30), IGREJA_MEMBRO TINYINT(1) NOT NULL, IGREJA_FREQ_REGULAR TINYINT(1) NOT NULL, IGREJA_TEMPO VARCHAR(100),
  IGREJA_PASTOR_NOME VARCHAR(200), IGREJA_PASTOR_EMAIL VARCHAR(200), IGREJA_LIDER_NOME VARCHAR(200), IGREJA_LIDER_EMAIL VARCHAR(200),
  IGREJA_ATIVIDADES_ENVOLVIDAS TEXT, IGREJA_DESVIOU TINYINT(1) NOT NULL, IGREJA_HABILIDADES TEXT,
  IGREJA_FE_PALAVRA_INSPIRADA TINYINT(1) NOT NULL, IGREJA_FE_TRINDADE TINYINT(1) NOT NULL, IGREJA_FE_JESUS TINYINT(1) NOT NULL,
  ESCOLHA_SEMINARIO TEXT, DATA_CONVERSAO DATETIME, DATA_BATISMO DATETIME, IGREJA_BATISMO VARCHAR(200), JUSTIFICATIVA_SALVACAO TEXT,
  DOENCAS_LIMITACOES TEXT, TRANSTORNO_DOENCA TINYINT(1) NOT NULL, REMEDIO_CONTROLADO TEXT, ALERGIA_MEDICAMENTO TEXT, SAUDE_OBSERVACAO TEXT,
  EMERGENCIA_NOME VARCHAR(200), EMERGENCIA_PARENTESCO VARCHAR(100), EMERGENCIA_TELEFONE VARCHAR(30), EMERGENCIA_CELULAR VARCHAR(30),
  DE_ACORDO TINYINT(1) NOT NULL, URL_COMP_ESCOLARIDADE VARCHAR(500), URL_RG VARCHAR(500), URL_CPF VARCHAR(500), URL_COMP_RESIDENCIA VARCHAR(500),
  URL_CERTIDAO_CASAMENTO VARCHAR(500), URL_CARTA_PASTORAL VARCHAR(500), URL_CONTRATO VARCHAR(500),
  STATUS_APROVACAO INT NOT NULL, JUSTIFICATIVA_REPROVACAO TEXT, DATA_INSCRICAO DATETIME, FORMA_PAGAMENTO INT NOT NULL
);
ALTER TABLE USUARIO
  ADD LISTA_ESTADO_CIVIL_ID BIGINT NOT NULL DEFAULT 1, ADD RG VARCHAR(30), ADD SEXO VARCHAR(1), ADD NACIONALIDADE VARCHAR(100),
  ADD NATURALIDADE VARCHAR(100), ADD FILIACAO VARCHAR(300), ADD EMAIL_RESPONSAVEL VARCHAR(200), ADD IGREJA VARCHAR(200),
  ADD PASTOR VARCHAR(200), ADD DESCONTO DECIMAL(10,2) NOT NULL DEFAULT 0, ADD DIA_VENCIMENTO INT NOT NULL DEFAULT 10, ADD DATA_CADASTRO DATETIME;
ALTER TABLE CONTAS_RECEBER ADD DATA_EDICAO DATETIME NULL, ADD DATA_CADASTRO DATETIME NULL;
ALTER TABLE LISTA_PROFESSOR ADD EMAIL VARCHAR(200), ADD TELEFONE VARCHAR(30), ADD CPF VARCHAR(20), ADD RG VARCHAR(30), ADD DATA_NASCIMENTO DATETIME,
  ADD ESTADO_CIVIL VARCHAR(50), ADD NOME_MAE VARCHAR(200), ADD URL VARCHAR(500), ADD DESCRICAO TEXT, ADD BANCO VARCHAR(100),
  ADD AGENCIA VARCHAR(20), ADD CONTA VARCHAR(30), ADD OBSERVACAO TEXT, ADD SENHA VARCHAR(100);

INSERT INTO LISTA_ESTADO_CIVIL VALUES (1,'SOLTEIRO(A)'),(2,'CASADO(A)'),(3,'DIVORCIADO(A)'),(4,'VIÚVO(A)');
UPDATE LISTA_PROFESSOR SET SENHA = 'texto-puro-legado';
